files.app/app.css:
.text-entry { flex:1 1 auto; min-height:80px; width:100%; resize:none; font:14px Arial,sans-serif; padding:4px; border:1px solid #bccbdc; }
* { box-sizing: border-box; }
:root { color: #20334a; background: #edf2f7; font-family: Arial, sans-serif; font-size: 15px; }
body { margin: 0; }
.shell { width: min(100%, 1040px); margin: auto; padding: 24px; }
h1, h2, p { margin: 0; }
h1 { font-family: Georgia, serif; font-size: 28px; line-height: 34px; }
h2 { font-size: 17px; line-height: 24px; }
button, input, select { font: inherit; color: inherit; }
button { min-height: 36px; border: 1px solid #8094ac; border-radius: 4px; background: white; padding: 7px 12px; cursor: pointer; white-space: nowrap; }
button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible { outline: 2px solid #1859a6; outline-offset: 2px; }
input, select { min-width: 0; height: 36px; border: 1px solid #8094ac; border-radius: 4px; background: white; padding: 7px 10px; }
.masthead { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-bottom: 20px; }
.eyebrow { color: #45678b; font-size: 12px; letter-spacing: 2px; text-transform: uppercase; margin-bottom: 4px; }
#global-status { padding: 10px; color: #8a251a; background: #fff0e9; margin-bottom: 12px; }
.toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: 12px 24px; padding-bottom: 12px; }
.action-group { display: flex; align-items: center; gap: 8px; }
#search { width: 180px; }
.search-panel { border-top: 1px solid #bccbdc; padding: 10px 0; }
#results { display: flex; align-items: center; gap: 16px; }
#results a { color: #1859a6; text-decoration: underline; }
.workspace { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; }
.document-pane { min-width: 0; height: 370px; padding: 16px; background: white; border: 1px solid #bccbdc; display: flex; flex-direction: column; }
.document-heading { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 12px; flex-shrink: 0; }
.document-text { flex: 1 1 auto; min-height: 80px; width: 100%; resize: none; border: 1px solid #bccbdc; padding: 16px; font-family: monospace; font-size: 16px; line-height: 24px; color: #20334a; background: #f8fafc; scrollbar-gutter: stable; }
.document-footer { flex-shrink: 0; display: flex; justify-content: space-between; margin-top: 8px; font-size: 12px; line-height: 18px; color: #45678b; }
.reference-pane { display: none; background: #dce8f3; padding: 16px; }
.reference-pane p { margin-top: 12px; line-height: 22px; }
.workspace.split { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
.workspace.split .reference-pane { display: block; }
.workspace.split .document-pane { height: 282px; }
.save-notice { flex: 0 0 auto; max-height: 85px; overflow: auto; padding: 8px; background: #fff0e9; border-left: 3px solid #a43d2d; margin-bottom: 8px; }
.notice-top { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
#save-detail { font-size: 13px; line-height: 18px; margin-top: 5px; }
.settings { margin-top: 20px; }
.settings h2 { margin-bottom: 12px; }
.preference-row { display: grid; grid-template-columns: 300px minmax(0, 1fr) auto; align-items: center; gap: 12px; margin-top: 12px; }
.preference-row .apply { min-width: 80px; }
.preference-row label { line-height: 20px; }
.preference-row .preference-select { width: 100%; appearance: none; padding-right: 28px; background-image: linear-gradient(45deg, transparent 50%, #20334a 50%), linear-gradient(135deg, #20334a 50%, transparent 50%); background-position: calc(100% - 15px) 15px, calc(100% - 10px) 15px; background-size: 5px 5px; background-repeat: no-repeat; }
.modal-backdrop { position: fixed; inset: 0; display: flex; align-items: center; justify-content: center; background: #142b4480; padding: 20px; }
.dialog-frame { width: 400px; max-width: 100%; background: white; border: 1px solid #8094ac; border-radius: 6px; box-shadow: 0 12px 36px #102a4440; padding: 24px; }
.dialog-heading { display: flex; align-items: center; gap: 10px; padding-bottom: 16px; margin-bottom: 16px; border-bottom: 1px solid #bccbdc; }
.document-mark { display: grid; place-items: center; width: 28px; height: 28px; background: #1859a6; color: white; font-family: Georgia, serif; }
#name-form { display: flex; flex-direction: column; gap: 8px; }
#name-error { line-height: 24px; color: #8a251a; font-size: 13px; }
#modal-actions { display: flex; justify-content: flex-end; gap: 8px; }
#confirm { background: #1859a6; border-color: #1859a6; color: white; }
[hidden] { display: none !important; }
@media (max-width: 700px) {
 .shell { padding: 16px; }
 .preference-row { grid-template-columns: minmax(0, 1fr) auto; }
 .preference-row .apply { min-width: 80px; }
.preference-row label { grid-column: 1 / -1; }
 .workspace.split { grid-template-columns: minmax(0, 1fr); }
}

.document-results { min-height: 36px; }
.feedback-slot { min-height: 24px; }

